USE hms;
CREATE TABLE IF NOT EXISTS departments(id INT AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(60) NOT NULL,icon VARCHAR(10),sort INT DEFAULT 0) DEFAULT CHARSET=utf8mb4;
